\section{Proof of Theorem \ref{yu-theorem-9-01-1}}\label{yu-section-4}
    We start this section with a lemma,  which plays a key role in the proof of Theorem \ref{yu-theorem-9-01-1}.
\begin{lemma}\label{yu-lemma-11-29-1}
    $\mathbb{C}=\{z-\kappa e^{-z\tau}:z\in\mathbb{C}\}$ for each $\kappa\in\mathbb{R}$ and $\tau>0$.
\end{lemma}
\begin{proof} Fix  $\kappa\in\mathbb{R}$ and $\tau>0$ arbitrarily.
    Let $\mathbb{D}_{\kappa,\tau}:=\{z-\kappa e^{z\tau}:z\in\mathbb{C}\}$. It suffices  to show that
\begin{equation}\label{yu-11-29-1}
    \mathbb{C}\subset\mathbb{D}_{\kappa,\tau}.
\end{equation}
  There are two possibilities: $\kappa=0$ or $\kappa\not=0$.  When $\kappa=0$, (\ref{yu-11-29-1}) is clear. In the rest of the proof, we suppose that $\kappa\neq 0$. For each $\eta=\eta_1+ i\eta_2\in\mathbb{C}$ with $\eta_1, \eta_2\in\mathbb{R}$, we aim to find $z:=z_1+ \mathrm{i}z_2\in \mathbb{C}$ with $z_1,z_2\in\mathbb{R}$ so that
\begin{equation}\label{yu-9-3-1}
    z-\kappa e^{-z\tau}=\eta.
\end{equation}
    Fix $\eta=\eta_1+ i\eta_2\in\mathbb{C}$ with $\eta_1, \eta_2\in\mathbb{R}$ arbitrarily. It is obvious that the solvability of the equation \eqref{yu-9-3-1} is equivalent to the solvability of the following two equalities:
\begin{equation}\label{yu-9-6-2}
    a^{-1}\xi_1e^{\xi_1}=\cos (\xi_2-\eta_2\tau)\;\;\mbox{and}\;\;
    a^{-1}\xi_2e^{\xi_1}=-\sin(\xi_2-\eta_2\tau).
\end{equation}
    Indeed, if there exists $(\xi_1,\xi_2)^\top\in\mathbb{C}$ so that the  equalities
    \eqref{yu-9-6-2} hold, then $z=z_1+\mathrm{i}z_2$ with
    $(z_1,z_2):=(\tau^{-1}\xi_1+\eta_1, \eta_2-\tau^{-1}\xi_2)^\top$
    is the solution of \eqref{yu-9-3-1}. We now show the the solvability of the equalities \eqref{yu-9-6-2}.
\par
    Firstly, we show the statement \textbf{(CL)}: $(\xi_1,\xi_2)\in \mathbb{R}^2$ satisfies \eqref{yu-9-6-2} if and only if $(\xi_1,\xi_2)\in \mathbb{R}^2$ satisfies the following estimates:
    \begin{equation}\label{wang-10-29-1}
\begin{cases}
        \xi_1\cos (\xi_2-\eta_2\tau)\geq 0,\;\;
   \xi_2\sin(\xi_2-\eta_2\tau)\leq 0,&\mbox{if}\;\;a>0,\\
   \xi_1\cos (\xi_2-\eta_2\tau)\leq 0,\;\;
   \xi_2\sin(\xi_2-\eta_2\tau)\geq 0,&\mbox{if}\;\;a<0,
\end{cases}
\end{equation}
and
\begin{equation}\label{wang-10-29-2}
    \xi_2=\pm \sqrt{a^2e^{-2\xi_1}-\xi_1^2},\;\;
   \xi_1 \sin(\xi_2-\eta_2 \tau)=-\xi_2\cos(\xi_2-\eta_2\tau).
\end{equation}
    Indeed,  if $(\xi_1,\xi_2)\in \mathbb{R}^2$ satisfies \eqref{yu-9-6-2}, it is clear that $(\xi_1,\xi_2)$ satisfies (\ref{wang-10-29-1})
    and \eqref{wang-10-29-2}. Conversely, if $(\xi_1,\xi_2)\in \mathbb{R}^2$ satisfies (\ref{wang-10-29-1})
    and \eqref{wang-10-29-2}, then there are two possibilities: $\xi_1=0$ or $\xi_1\not=0$. When $\xi_1=0$,
     it follows from \eqref{wang-10-29-2} that  $\xi_2=\pm a$ and $\cos(\xi_2-\eta\tau)=0$. These imply the first equality in \eqref{yu-9-6-2}.
     Further, by \eqref{wang-10-29-1}, we have that
    $\sin(\xi_2-\eta_2\tau)=\begin{cases}
    -1&\mbox{if}\;\;\xi_2=a,\\
    1&\mbox{if}\;\;\xi_2=-a,
\end{cases}$ which indicates the second equality in \eqref{yu-9-6-2}. When $\xi_1\neq 0$, it follows from \eqref{wang-10-29-2} that
$\xi_1^2=(\xi_1^2+\xi_2^2)(\cos(\xi_2-\eta_2\tau))^2
    =a^2e^{-2\xi_1}(\cos(\xi_2-\eta_2\tau))^2$,
    which, combined with \eqref{wang-10-29-1}, indicates that $(\xi_1,\xi_2)$ satisfies the first equality in \eqref{yu-9-6-2}.
    The second equality in \eqref{yu-9-6-2} follows from the first equality in \eqref{yu-9-6-2} and  the second equality in \eqref{wang-10-29-2}
    immediately.

\par
    Secondly, let $\mathbb{I}_j:=\mathbb{R}\times[j\pi+\eta_2\tau,(j+1)\pi+\eta_2\tau)$ for each $j\in\mathbb{Z}$,
    $\mathbb{A}:=\{(\xi_1,\xi_2)\in\mathbb{R}^2:\xi_2=\pm \sqrt{a^2e^{-2\xi_1}-\xi_1^2}\}$ and $\mathbb{B}:=\{(\xi_1,\xi_2)\in\mathbb{R}^2:\xi_1 \sin(\xi_2-\eta_2 \tau)=
    -\xi_2\cos(\xi_2-\eta_2\tau)\}$.
   Then $\mathbb{R}^2=\cup_{j\in\mathbb{Z}}\mathbb{I}_j$ and there exists $j_1^*:=j^*_1(\eta,\tau)\in\mathbb{N}^+$ so that  the function $f(s)=-s\cot(s-\eta_2\tau)$ has the following properties:
\begin{itemize}
  \item [$(a_1)$]  For each $j\in\mathbb{Z}$ with $j\geq j^*_1$, it has only one zero-point $(j+\frac{1}{2})\pi+\eta_2\tau$ in $(j\pi+\eta_2\tau,(j+1)\pi+\eta_2\tau)$ and
  $|f(s)|\to+\infty$ when $s\to j\pi+\eta_2\tau$ and  $s\to(j+1)\pi+\eta_2\tau$;
  \item [$(a_2)$]  $f'(s)>0$ for $s\in (j\pi+\eta_2\tau,(j+1)\pi+\eta_2\tau)$ with $j\geq j_1^*$.
\end{itemize}
     According to $(a_1)$, $(a_2)$ and  the fact that $\sqrt{a^2e^{-2\xi_1}-\xi_1^2}\to+\infty$ as $\xi_1\to-\infty$, there exists $j_2^*:=j^*_2(\eta,\tau)\in\mathbb{N}^+$ with $j_2^*\geq j_1^*$ so that the following statements hold:
     \begin{enumerate}
       \item [$(a_3)$] For each $j\in\mathbb{Z}$ with $j\geq j^*_2$, the set $\mathbb{R}^2_-\cap
    \mathbb{A}\cap \mathbb{B}\cap \mathbb{I}_j$ has only one element, where $\mathbb{R}^2_-:=\{(x_1,x_2)\in\mathbb{R}^2:x_1<0\}$;
       \item [$(a_4)$] When $j\geq j^*_2$, $f(s)<0$ if $s\in(j\pi+\eta_2\tau,
    (j+\frac{1}{2})\pi+\eta_2\tau)$ and $f(s)>0$ if $s\in((j+\frac{1}{2})\pi+\eta_2\tau,
    (j+1)\pi+\eta_2\tau)$;
       \item [$(a_5)$]  For each $j\in\mathbb{Z}$ with $j\geq j^*_2$, $(-\infty,0)\times\{ j\pi+\eta_2\tau\}\notin \mathbb{A}\cap \mathbb{B}\cap \mathbb{I}_j$.
     \end{enumerate}

