ref_dict.thm full Fourier expansion:
\begin{thm}\label{thm full Fourier expansion}
Suppose $\ell> n$, $D\equiv 3\modulo 4$ and $n\equiv 2\modulo 4$. 
The constant term along $\bff{Z}$ of the Eisenstein series   
$E_\ell(g, s=\ell+1)$ has the Fourier expansion 
\begin{align*}
   E_{\ell,0}(g)+\sum_{\substack{0\neq T\in\bff{V}_{0}\\\lrangle{T}{T}\geq 0}}a_{T}(g_{f})\call{W}_{T}(g_{\infty}),\,g=g_{f}g_{\infty}\in\bff{G}(\A_{f})\times \bff{G}(\R),
\end{align*}
where the Fourier coefficients satisfy:
\begin{itemize}
    \item The locally constant functions $a_{T}(g_{f})$ are valued in $\Q$ when restricted to $g_{f}\in\bff{M}(\A_{f})$.
    \item The $\bff{N}$-constant term $E_{\ell,0}(g)$ is a rational multiple of $|\nu(g)|_{\A_{E}}^{\ell+1}\frac{\zeta_{E}(\ell+1)}{\pi^{2\ell+1}}[u_{1}^{n}][u_{2}^{n}]$ when restricted to $g\in \bff{M}(\A)$.
\end{itemize}
Moreover, when $g_{f}=1$, 
$E_{\ell}(g_{\infty},s=\ell+1)$ have the following explicit Fourier expansion:
\begin{align*}
   E_{\ell,0}(g_\infty)+C_{\ell}\sum_{0\neq T\in\bff{V}_{0}(\Z)\atop \lrangle{T}{T}=0}\sigma_{E,\ell}(T)\call{W}_{T}(g_{\infty})
    +D_{n,\ell}\sum_{T\in\bff{V}_{0}(\Z)\atop \lrangle{T}{T}>0}\left(\prod_{p|\lrangle{T}{T}}Q_{T,p}(p^{\ell-\frac{n-1}{2}})\right)\call{W}_{T}(g_{\infty}),
\end{align*}
where
\[C_{\ell}=\frac{(-1)^{\ell}2^{2\ell+1}}{(\ell!)^{2}}\quad \text{and} \quad D_{n,\ell}=\frac{2^{2n+2}(2\ell-n+2)D^{\ell+1-\frac{n}{2}}}{(\ell!)^{2}\left|B_{2\ell-n+2}\right|\sigma_{\ell+1-\frac{n}{2}}(D)} \in \Bbb Q.\]
\end{thm}

expanded_theorem:
\label{main theorem} We first prove the following theorem. \begin{thm}\label{thm full Fourier expansion}
Suppose $\ell> n$, $D\equiv 3\modulo 4$ and $n\equiv 2\modulo 4$. 
The constant term along $\bff{Z}$ of the Eisenstein series   
$E_\ell(g, s=\ell+1)$ has the Fourier expansion 
\begin{align*}
   E_{\ell,0}(g)+\sum_{\substack{0\neq T\in\bff{V}_{0}\\\lrangle{T}{T}\geq 0}}a_{T}(g_{f})\call{W}_{T}(g_{\infty}),\,g=g_{f}g_{\infty}\in\bff{G}(\A_{f})\times \bff{G}(\R),
\end{align*}
where the Fourier coefficients satisfy:
\begin{itemize}
    \item The locally constant functions $a_{T}(g_{f})$ are valued in $\Q$ when restricted to $g_{f}\in\bff{M}(\A_{f})$.
    \item The $\bff{N}$-constant term $E_{\ell,0}(g)$ is a rational multiple of $|\nu(g)|_{\A_{E}}^{\ell+1}\frac{\zeta_{E}(\ell+1)}{\pi^{2\ell+1}}[u_{1}^{n}][u_{2}^{n}]$ when restricted to $g\in \bff{M}(\A)$.
\end{itemize}
Moreover, when $g_{f}=1$, 
$E_{\ell}(g_{\infty},s=\ell+1)$ have the following explicit Fourier expansion:
\begin{align*}
   E_{\ell,0}(g_\infty)+C_{\ell}\sum_{0\neq T\in\bff{V}_{0}(\Z)\atop \lrangle{T}{T}=0}\sigma_{E,\ell}(T)\call{W}_{T}(g_{\infty})
    +D_{n,\ell}\sum_{T\in\bff{V}_{0}(\Z)\atop \lrangle{T}{T}>0}\left(\prod_{p|\lrangle{T}{T}}Q_{T,p}(p^{\ell-\frac{n-1}{2}})\right)\call{W}_{T}(g_{\infty}),
\end{align*}
where
\[C_{\ell}=\frac{(-1)^{\ell}2^{2\ell+1}}{(\ell!)^{2}}\quad \text{and} \quad D_{n,\ell}=\frac{2^{2n+2}(2\ell-n+2)D^{\ell+1-\frac{n}{2}}}{(\ell!)^{2}\left|B_{2\ell-n+2}\right|\sigma_{\ell+1-\frac{n}{2}}(D)} \in \Bbb Q.\]
\end{thm}
Assume that the discriminant of $E$ is odd. When $\ell>n$, the Eisenstein series $E_\ell(g)$ has rational Fourier coefficients in the following sense:
\begin{itemize}
    \item The locally constant functions $a_{T}(E_{\ell},g_{f})$ take values in $\mathbb{Q}$ when restricted to $\mathbf{M}(\A_{f})$.
    \item The constant term $E_{\ell,\mathbf{N}}(g)$ is a rational multiple of $|\nu(g)|_{\A_{E}}^{\ell+1}\cdot\frac{\zeta_{E}(\ell+1)}{\pi^{2\ell+1}}[u_{1}^{n}][u_{2}^{n}]$ when restricted to $\mathbf{M}(\mathbb{A})$, where $[u_{1}^{n}][u_{2}^{n}]$ denotes a vector in a fixed basis of $\mathbb{V}_{\ell}$.
\end{itemize}
Moreover, the value of the $T$th Fourier coefficient $a_{T}(E_{\ell},g_{f})$ at $g_{f}=1$ is non-zero if and only if $T$ lies in a self-dual Hermitian $\oo_{E}$-lattice $\mathbf{V}_{0}(\mathbb{Z})$ of $\mathbf{V}_{0}$. We have an explicit formula for the Fourier coefficients $a_{T}(E_{\ell},1)$, and their denominators are all divisors of an integer depending only on $E,\ell$, and $n$.

theorem.content:
[Baldauf--Ozuch \cite{BaldaufOzuch22}; Chu--Zhu \cite{ChuZhu24}]\label{thm-BO-CZ}
		Let $(M^n,g,e^{-f}dV_g)$ be an asymptotically flat weighted manifold with $R_f\in L^1(M)$. Assume either $3\le n\le 7$ or $M$ is spin.

		Then if $R_f\ge 0$, $\m_f(g)\ge 0$ with equality if and only if $(M^n,g)$ is isometric to Euclidean space and $f\equiv0$.

ref_dict.def-weighted-min:
\begin{defn} \label{def-weighted-min}
		We say a hypersurface in a weighted manifold $(M^n,g,e^{-f}dV_g)$ is \emph{$f$-minimal} if the weighted mean curvature $H_f=H-\partial_\nu f$ of the hypersurface vanishes. We further say that a closed hypersurface $\Sigma$ in a weighted manifold is \emph{$f$-outer-minimising} if it minimises the weighted area over all hypersurfaces enclosing $\Sigma$.
	\end{defn}

ref_dict.def-AF:
\begin{defn}\label{def-AF}
		A \emph{weighted manifold} (or manifold with density) is a triple $(M^n,g,e^{-f}dV_g)$, where $f\in C^\infty(M)$ and the reference measure is $e^{-f}dV_g$. We say a weighted manifold is asymptotically flat of order $\tau>\frac{n-2}{2}$ if $(M^n,g)$ is asymptotically flat of order $\tau$ and $f=O_2(r^{-\tau})$.
	\end{defn}

post_theorem_intro_text:
The reader is directed to definition \ref{def-AF} for the assumed decay rates for asymptotically flat weighted manifolds.

	Somewhat surprisingly, Law, Lopez, and Santiago \cite{LawLopezSantiago24} showed that after a particular conformal transformation, the weighted positive mass theorem reduces precisely to the usual (unweighted) positive mass theorem, which can then be applied directly. In fact, the result they obtain is actually stronger than the previously established more technical proofs.
	\begin{thm}[Law--Lopez--Santiago \cite{LawLopezSantiago24}]\label{thm-LLS}
		Let $(M^n,g,e^{-f}dV_g)$ be an asymptotically flat weighted manifold with $f=o_2(|x|^{-(n-2)/2})$ and $R_f\in L^1(M)$. Set
		\[
		\widetilde g \;=\; e^{-\frac{2}{n-1}f}\,g.
		\]
		Then the scalar curvature of $\widetilde g$, $\widetilde R$ is given by
		\[
		\widetilde R \;=\; e^{\frac{2}{n-1}f}\Big(R_f + \frac{1}{n-1}\,|\nabla f|^2\Big),
		\]
		and
		\[
		\m_f(g) \;=\; \mathfrak{m}(\widetilde g).
		\]
		In particular, if $R_f\ge -\frac{1}{n-1}|\nabla f|^2$ then $R_{\widetilde g}\ge 0$ and hence $\m_f(g)\ge 0$.
	\end{thm}
	Without this insight, one may be tempted to pursue a proof of a weighted Riemannian Penrose inequality by adapting the proofs of Huisken and Ilmanen \cite{HuiskenIlmanen01} or Bray \cite{Bray01} to the weighted setting\footnote{The present author at least was, prior to learning of the article \cite{LawLopezSantiago24}.}. However, it turns out that the expected weighted Riemannian Penrose inequality follows from the same conformal transformation then applying the standard Riemannian Penrose inequality to the conformal metric. In this note, we show this weighted Riemannian Penrose inequality and some related results on weighted manifolds that follow from this same conformal picture. In order to better understand why this approach works so well, we investigate the quantity $$S_f=R_f+\frac{1}{n-1}|\nabla f|^2.$$ In particular, we study the geometric mass invariant associated with $S_f$ via Michel's mass invariant formalism \cite{Michel11}, and establish that it is precisely the weighted mass. 
	\begin{thm}\label{thm-Michel}
		Let $(M^n,g,e^{-f}dV_g)$ be an asymptotically flat weighted manifold and define the densitised curvature operator $\Phi(g,f)=S_f(g)\,e^{-f}dV_g$. The kernel of $D\Phi^*_{(\mathring g,0)}$ consists of affine functions $V$ defining geometric mass invariants in the sense of Michel \cite{Michel11}
		\begin{equation}
			\mathfrak{m}(g,f,V)=\lim_{\rho\to\infty}\int_{S_\rho}\mathbb U_i(g,f,V)\,\nu^idS,
		\end{equation}
		where $\mathbb U(g,f,V)$ satisfies
		\begin{equation*}
			\div_{\mathring g}\mathbb U(g,f,V)=V\, D\Phi_{(\mathring g,0)}.
		\end{equation*}
		Furthermore, for $V=1$ and assuming $S_f\in L^1$ then we have
		\begin{equation*}
			\mathfrak{m}(g,f,1)=\m_f(g).
		\end{equation*}
	\end{thm}

	With this in mind, it is not surprising that we can establish so many properties of the weighted mass via the conformal metric $\widetilde g$, whose scalar curvature is $S_f$.  This framework also naturally leads to a definition of centre of mass for weighted manifolds, which agrees with the standard (unweighted) centre of mass of $\widetilde g$.

	Examining the linearisation of $S_f$ and its formal adjoint leads to a natural definition of weighted static metrics, which can be understood as candidates for minimisers of the weighted mass. We prove that this definition of weighted staticity also can be understood via the conformal metric $\widetilde g$. From this we prove the following weighted static uniqueness theorem for what we call the $f$-Schwarzschild family of metrics, which differ from regular Schwarzschild metrics by the conformal factor $e^{-\frac{2f}{n-1}}$ (see Definition \ref{def-f-schwarzschild}).
	\begin{thm}\label{thm-fstatic-bh-rigidity-intro}
		Let $(M^n,g,e^{-f}dV_g)$ be an asymptotically flat weighted manifold with compact boundary
		$\Sigma=\partial M$, and assume $f\to 0$ at infinity.
		Assume either $3\le n\le 7$ or $M$ is spin, and for $n>3$ further assume $\Sigma$ is connected.

\noindent 		Suppose there exists an $f$-static potential $V\in C^\infty(M)$ satisfying
		\[
		V>0\ \text{on }M\setminus\Sigma,\qquad V=0\ \text{on }\Sigma,\qquad V\to 1\ \text{at infinity}.
		\]

	\noindent 	Then $(M^n,g,e^{-f}dV_g)$ is $f$-Schwarzschild of mass $m=\m_f(g)$.
	\end{thm}
	\newpage
	Many other geometric quantities have natural weighted versions that fit together within a coherent weighted manifold framework (see Table 1 of \cite{BaldaufOzuch22}, for example). This leads to natural definitions of weighted minimal surfaces, weighted outer-minimising surfaces (see Definition \ref{def-weighted-min}), and to conjecture a weighted Riemannian Penrose inequality. However, we show this follows immediately from the conformal transformation discussed above.
	\begin{thm}\label{thm-weightedPenrose-intro}
		Let $(M^n,g,e^{-f}dV_g)$ be a weighted asymptotically flat manifold of dimension $3\le n\le 7$ containing a closed $f$-outer-minimising $f$-minimal hypersurface $\Sigma$. Assume $S_f\ge 0$, then
		\begin{equation}\label{eq-weightedPenrose}
			m_f(g)\;\ge\;\frac12\left(\frac{A_f(\Sigma)}{\omega_{n-1}}\right)^{\!\frac{n-2}{n-1}}.
		\end{equation}
		Furthermore, if we also assume that $M$ is spin\footnote{Recall $n=3$ implies spin automatically.}, then equality holds in \eqref{eq-weightedPenrose} if and only if $(M^n,g,e^{-f}dV_g)$ is an $f$-Schwarzschild manifold.
	\end{thm}

	We remark that it appears as though much of what one might want to study in connection to this weighted mass ultimately can be reduced to the unweighted situation by means of this straightforward conformal transformation.

