\begin{proposition}
\label{prop:doubleladderker}
The kernel of the intertwining operator $(s-\frac{1}{3})A(0,s):I(0,s)\to I(0,\tilde{s})$ at $s = \frac{1}{3}$ is the double ladder representation of $G$. It is also the image of the intertwiner $A(0,\tilde{s}):I(0,\tilde{s})\to I(0,s)$. Moreover, this subrepresentation has $K$-types $\sigma(3m,m)$ and $\sigma(3m+4,m)$ ($m\in\ZZ_{\geq0}$) with corresponding embedding vectors $v_{3m,m}(s,0)$ and $v_{3m+4,m}(s,0)$.
\end{proposition}

