\begin{theorem}[Corollary \ref{hyperelliptic}]\label{hypell}
    Let $X$ be a smooth projective variety that admits an \'etale Galois cover $Y\to X$, where $Y$ is an abelian variety.
    Then the set-theoretic image of $h^r:M^r_{X,\text{Dol}}\to A^{r,\Omega^1_X}_X$ coincides with the subset $(H^0(Y,\Omega^1_Y)^r\sslash S_r)^G$
    of $A^{r,\Omega^1_Y}_Y$, where $G:=\gal(Y/X)$ and $S_r$ denotes the symmetric group in $r$ letters.

    In particular, if $X$ is an abelian variety, we have $\mathrm{im}(h^r)=H^0(X,\Omega^1_X)^r\sslash S_r$.
\end{theorem}

