\begin{lem}[Generalised Constant Speed Solutions]\label{lem: const2}
    Given a graph $\GG$ and $(P,\epsilon)$ a valid choice for inverting $\Omega$, define the \textit{Constant Speed Solution} associated to $(P,\epsilon)$ to be
    \begin{equation}
        v_k = \text{sign}(P \cdot \tilde{f} + \epsilon)_k|v|, \quad g_k = |P \cdot \tilde{f} + \epsilon|_k/|v|
    \end{equation}
     where $|v| = \sum_{k \in \VV} |P \cdot \tilde{f} + \epsilon|_k$. Then the constant speed solution minimizes $\mathcal{I}_q(v,g)$ over the pairs $(v,g)$ associated to $(P,\epsilon)$, i.e pairs which satisfy \eqref{eq: reducedcond}.
\end{lem}

