ref_dict.rm:Serre=thick:
\begin{remark}\rm\label{rm:Serre=thick}
Let $\mathcal{C}$ be a multiring category and $\mathcal{M}$ be a left $\mathcal{C}$-module category. Suppose $\mathcal{N}$ is a Serre submodule category of $\mathcal{M}$. Using \cite[Theorem 3.2]{Miy91}, we can show that $$ \mathbf{D}^{b}(\mathcal{M})/\mathbf{D}^{b}_{\mathcal{N}}(\mathcal{M})\approx \mathbf{D}^{b}(\mathcal{M}/\mathcal{N})$$ as triangulated module categories over $\mathbf{D}^b(\mathcal{C})$, where $\mathbf{D}^{b}_{\mathcal{N}}(\mathcal{M})$ is a full subcategory of $\mathbf{D}^{b}(\mathcal{M})$ generated by complexes of which all homologies are in $\mathcal{N}.$ A corresponding version of the statement holds for monoidal triangulated categories.
\end{remark}

ref_dict.prop:kunneth:
\begin{proposition}\label{prop:kunneth}
Let $\mathcal{T}$ be a monoidal triangulated category equipped with a compatible bounded t-structure $\mathbbm{t}$, and let $\mathcal{K}$ be a triangulated module category over $\mathcal{T}$ endowed with a bounded t-structure $\mathbbm{t}^\prime$. Suppose that the module product bifunctor is compatible with $\mathbbm{t}$ and $\mathbbm{t}^\prime$. Then for objects $X\in\mathcal{T}$, $M\in\mathcal{K}$ and an integer $n$, there is a natural isomorphism
$$
H^n_{\mathbbm{t}^\prime}(X\otimes M)\cong \coprod\limits_{p+q=n} H^p_{\mathbbm{t}^\prime}(X)\otimes H^q_{\mathbbm{t}^\prime}(M).
$$
\end{proposition}

ref_dict.thm:thick=serre:
\begin{theorem}\label{thm:thick=serre}
Let $\mathcal{C}$ and $\mathcal{D}$ be tensor categories, and let subcategories $\mathcal{A} \subset \mathcal{C}$ and $\mathcal{B} \subset \mathcal{D}$ be abelian categories with finitely many isomorphism classes of simple objects. Assume further that $\mathbf{D}^b(\mathcal{A})$ and $\mathbf{D}^b(\mathcal{B})$ are left triangulated tensor ideals of $\mathbf{D}^b(\mathcal{C})$ and $\mathbf{D}^b(\mathcal{D})$, respectively. Suppose $F:\mathbf{D}^b(\mathcal{C})\rightarrow \mathbf{D}^b(\mathcal{D})$ is a monoidal triangulated functor such that $F(\mathbf{D}^b(\mathcal{A}))\subseteq \mathbf{D}^b(\mathcal{B})$. If $F\mid_{\mathbf{D}^b(\mathcal{A})}$ is full and dense, then
\begin{itemize}
\item[(1)]$F(\mathcal{A})\subseteq \mathcal{B}$ and $F\mid_{\mathcal{A}}:\mathcal{A}\rightarrow \mathcal{B}$ is a $\mathcal{C}$-module functor.
\item[(2)]$\mathcal{A}/\ker(F\mid_{\mathcal{A}})$ is $\mathcal{C}$-module equivalent to $\mathcal{B}$.
\item[(3)]$\ker(F\mid_{\mathbf{D}^b(\mathcal{A})})=\mathbf{D}^{b}_{\ker(F\mid_{\mathcal{A}})}(\mathcal{A})$, where $\mathbf{D}^{b}_{\ker(F\mid_{\mathcal{A}})}(\mathcal{A})$ is a full subcategory of $\mathbf{D}^{b}(\mathcal{A})$ generated by complexes of which homologies are in $\ker(F\mid_{\mathcal{A}}).$
\end{itemize}
\end{theorem}

